CREATE TABLE students (id INTEGER PRIMARY KEY AUTOINCREMENT, agency TEXT NOT NULL, name TEXT NOT NULL, position TEXT NOT NULL, extras TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(agency,name,position));
CREATE TABLE rooms (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, cols INTEGER NOT NULL DEFAULT 8, rows INTEGER NOT NULL DEFAULT 8, podium_x INTEGER NOT NULL DEFAULT 4, podium_y INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE seats (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, x INTEGER NOT NULL, y INTEGER NOT NULL, UNIQUE(room_id,x,y));
CREATE TABLE aisles (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, x INTEGER NOT NULL, y INTEGER NOT NULL, UNIQUE(room_id,x,y));
CREATE TABLE sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, room_id INTEGER NOT NULL REFERENCES rooms(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(date,room_id));
CREATE TABLE assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL UNIQUE REFERENCES students(id), session_id INTEGER NOT NULL REFERENCES sessions(id), seat_id INTEGER NOT NULL REFERENCES seats(id), assessment_status TEXT NOT NULL DEFAULT '待考核', note TEXT NOT NULL DEFAULT '', assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id,seat_id));
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, action TEXT NOT NULL, detail TEXT NOT NULL);
